fn max_range_nearly_can_use(champ: &Entity, target: &Entity, tick: usize) -> u64

let mut range: u64 = 0;                                        // battle.rs:2398

// ── ① 평타 (battle.rs:2399~2404) ────────────────────────────
if champ.attack_effect(0x490).casting(0x4c0) != -1 {           // Option::as_ref, None 니치
    let e = &champ.attack_effect;
    if CastingTarget::check(&e.target(0x4b8), champ, target)    // 대상조건 (본문은 game_core, 미확인)
       && champ.attack_cooldown() <= tick {                     // battle.rs:2402, entity.rs:1747 인라인
        range = Effect::range(e, champ, target);                // battle.rs:2403 (초기값 0 이라 max 접힘)
    }
}

// ── ② 스킬 (battle.rs:2407~2411) ────────────────────────────
if champ.skill_effect(0x4c8).casting(0x4f8) != -1 {
    let e = &champ.skill_effect;
    if CastingTarget::check(&e.target(0x4f0), champ, target)
       && champ.skill_cooldown() <= tick {                      // battle.rs:2409, entity.rs:1775
        range = max(range, Effect::range(e, champ, target));    // battle.rs:2410 (llvm.umax.i64)
    }
}

// ── ③ 스킬2 (battle.rs:2414~2418) ───────────────────────────
let lv = champ.level(0x5c8);
let s2: &Option<Effect> = if lv > 2 { &champ.skill2_effect(0x500) }
                          else      { &STATIC_NONE };           // entity.rs:1693 (@anon...40)
if s2.casting(+48) != -1 {
    if CastingTarget::check(&s2.target(+40), champ, target)
       && champ.skill2_cooldown() <= tick {                     // battle.rs:2416, entity.rs:1790
        range = max(range, Effect::range(s2, champ, target));   // battle.rs:2417
    }
}

// ── ④ 궁 (battle.rs:2421~2425) ──────────────────────────────
let ul: &Option<Effect> = if lv > 4 { &champ.ult_effect(0x538) }
                          else      { &STATIC_NONE };           // entity.rs:1701
if ul.casting(+48) != -1 {
    if CastingTarget::check(&ul.target(+40), champ, target)
       && champ.ult_cooldown() <= tick {                        // battle.rs:2423, entity.rs:1805
        range = max(range, Effect::range(ul, champ, target));   // battle.rs:2424
    }
}
return range;                                                   // battle.rs:2429

